//
// The hill of hillclimb ([HILLCLIMB] 1), from its parameters alone:
// what voxel is at a place, so that a section is generated by asking this
// for each of its voxels, and the same parameters always give the same
// hill. No engine types (interface/noise.h is header only): the module
// and the self test (-DHILL_TEST) both include it.
//
// **A world unit is one voxel, 125 mm** (U = 8 to the metre): voxelworld
// has no scale, so every length in metres is multiplied by U on its way
// in, the car's and the camera's as well as the hill's.
//
// Along +Z: a flat pad at the bottom, the slope, a flat pad at the top.
// Across X: the track, 10 m, the voxel area's whole width
// ([HC_OPEN_EDGES]: no banks). Outside it no voxels: outside() is the
// ground there, which main.cpp puts a car back from and the client draws.
// Under the surface a shell of sand with pebbles (stones 2 to 3 voxels
// across) 1.5 m deep, then a fill nobody sees.
// The slope's angle is the middle's; its ends ease in and out over 2 m,
// so the car does not meet a kink at either pad.
// [HC_STEEP_NOISE] The angle varies over the slope by up to steep_var_deg
// either way, a smooth 2D noise of about 10 m waves: the local angle at
// (x, z) is steep_deg + steep_var_deg * n(x, z), and each column's height
// that angle's rise summed up the hill, so the steepness, not the height,
// is what varies (and the hill tilts a little sideways).
// [HC_PITS_ROCKS] On the slope, about one feature each 6 m: pits, bowls
// in the sand at its angle of repose, and rocks poking up from it, each
// left out where it would leave a cross-section less than 3 m free.
// [HC_CIRCUIT] A circuit: the area width_m wide, and on it a loop of
// lanes lane_m wide, each a straight strip along X or Z: right across
// the bottom, up the right side, left across the top, down the left side,
// the start line in the bottom lane's middle. A share of the slope's
// height (switchbacks) climbed by zigzags, the way up's in the right
// half, the way down's in the left, where along the slope by the seed.
// Every voxel is ground (the middle as well: see the done note); off the
// lanes is off the track, as off the area is (on_track()).
#pragma once
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <vector>
#include "interface/noise.h"

namespace hill {

static const int U = 8; // voxels to the metre
static const float PI = 3.14159265f;

// [HC_WET_SAND] WET: the wet, packed sand under the loose top's
enum Voxel { AIR, SAND, STONE, FILL, WET };

struct Params
{
	uint32_t seed = 1;
	float steep_deg = 22; // the middle's slope
	// [HC_STEEP_NOISE] The largest local departure from it, 0 to 10; 0 an
	// even slope (the game's default is main.cpp's)
	float steep_var_deg = 0;
	float length_m = 50;  // the slope's run along Z
	bool features = true; // pits and rocks ([HC_PITS_ROCKS]); off for a check
	// [HC_CIRCUIT] A circuit, its area's width, its lanes' and the share
	// of the slope climbed by switchbacks, 0 to 100
	bool circuit = false;
	float width_m = 40, lane_m = 7;
	int switchbacks = 50;
	// [HC_WET_SAND] The loose dry sand's depth over the wet, voxels, 0 to
	// 8 (the shell's 12 all loose before it); [HC_LOOSE_DEFAULT] one
	int loose = 1;
	// simplified: sand with pebbles is the only terrain; rocky, muddy and
	// vegetated are later ([HILLCLIMB] 5)
};

struct Hill
{
	Params p;
	// In voxels
	static const int PAD = 6 * U;      // each flat pad, longer than the car
	static const int EASE = 2 * U;     // the slope's ends, eased
	static const int TRACK_W = 10 * U; // the straight hill's
	int track_w = TRACK_W;             // the area's width
	static const int SHELL = 12;       // sand's depth, 1.5 m
	static const int BASE = 2 * U;     // the bottom pad's surface over y 0
	static const int BUMP = 1;         // the surface's undulation, voxels
	int run = 0;                       // the slope's run
	float k = 0;                       // the middle's rise per voxel
	float rise = 0;                    // the highest column's
	static const int VAR_CELL = 5 * U; // the steepness noise's cells
	// [HC_STEEP_NOISE] With a variance: each column's profile at every
	// whole z, size_z() + 1 a column
	std::vector<float> prof;

	// [HC_PITS_ROCKS] A pit or a rock, in voxels: its centre (x, z, and a
	// rock's y; a voxel's centre at +0.5, as a pebble's) and radius, and a
	// pit's depth
	enum Kind { PIT, ROCK };
	struct Feature { Kind kind; float x, y, z, r, depth; };
	std::vector<Feature> features;
	static const int FEATURE_EVERY = 6 * U; // one each, on average
	static const int FREE_W = 3 * U;        // kept free across the track
	static const int TOP_CLEAR = 4 * U;     // none this near the top pad
	static constexpr float REPOSE = 0.67f;  // tan 34 degrees, sand's

	// [HC_CIRCUIT] The loop: its turns, path[0] the start line's middle
	// (a voxel's centre at its integer position, as everywhere), and a
	// lane's width; a lane each segment, as a box from the segment
	// stretched by half a lane every way
	struct V2 { float x, z; };
	std::vector<V2> path;
	float lane = 0;
	struct Box { float x0, z0, x1, z1; };
	std::vector<Box> lanes;
	// A fence, along X or Z or a relief's diagonal, the area's edge's with
	// none
	struct Fence { float x0, z0, x1, z1; };
	std::vector<Fence> fences;
	// A turn's inner corner cut off (user, 2026-10-19: "the inner corners
	// need a bit of a relief (when one fits) as the car's turning radius
	// isn't that great"): the triangle from the corner c along both inner
	// fences, a and b its two ways out of the corner
	struct Relief { V2 c, a, b; float leg; size_t turn; };
	std::vector<Relief> reliefs;
	// [HC_MISSED_TURN_MARK] A hairpin's opening: where its two turns share
	// an inner corner, the fence between the ways in and out is cut back
	// by half a lane and left open. Its two triangles, each a relief's
	// shape: the way out's side (its first turn's corner) passes both
	// turns, the way in's the second once the first is (user, 2026-10-20:
	// "the line I drove should count as an acceptable turn"). n the first
	struct Gap { Relief r; size_t n; bool out; };
	std::vector<Gap> gaps;

	Hill(const Params &params): p(params)
	{
		if(p.circuit)
			track_w = std::max(1, (int)std::lround(p.width_m * U));
		run = (int)std::lround(p.length_m * U);
		k = std::tan(p.steep_deg * PI / 180);
		// Each eased end rises half of what a straight one would
		rise = k * (run - EASE);
		if(p.steep_var_deg > 0)
			vary();
		if(p.circuit){
			make_path();
		} else {
			// The area's edges
			const float x1 = size_x() - 0.5f, z1 = size_z() - 0.5f;
			fences = {{-0.5f, -0.5f, x1, -0.5f}, {x1, -0.5f, x1, z1},
					{-0.5f, z1, x1, z1}, {-0.5f, -0.5f, -0.5f, z1}};
		}
		if(p.features)
			place_features();
	}

	// [HC_CIRCUIT] The loop, in the area's own frame first (0 to its size
	// across its edges), moved by half a voxel at the end
	void make_path()
	{
		const float W = (float)track_w, Z = (float)size_z();
		const float w = std::fmin(p.lane_m * U, W / 2), h = w / 2, xm = W / 2;
		lane = w;
		// The runs across the slope a way's zigzag can have, an even
		// number: from a lane over the bottom one to a lane under the top
		// one; none where a half is under two lanes
		int most = W / 2 >= 2 * w && Z >= 3 * w ? (int)((Z - 3 * w) / w) + 1 : 0;
		most &= ~1;
		const int n = 2 * (int)std::lround(p.switchbacks / 100.0f * most / 2);
		const float first = h + w, last = Z - h - w - (n - 1) * w;
		const float up = first + unit(1, 0, 0, 211) * (last - first);
		const float down = Z - h - w - unit(2, 0, 0, 211) * (last - first);
		std::vector<V2> v;
		v.push_back({xm, h});
		v.push_back({W - h, h});
		for(int k = 0; k < n; k++){
			const float z = up + k * w;
			v.push_back({k % 2 ? xm + h : W - h, z});
			v.push_back({k % 2 ? W - h : xm + h, z});
		}
		v.push_back({W - h, Z - h});
		v.push_back({h, Z - h});
		for(int k = 0; k < n; k++){
			const float z = down - k * w;
			v.push_back({k % 2 ? xm - h : h, z});
			v.push_back({k % 2 ? h : xm - h, z});
		}
		v.push_back({h, h});
		// Each lane's box; its two sides fenced, each side stopped at the
		// inner corner of a turn and carried to the outer one
		std::vector<Fence> f;
		const size_t m = v.size();
		for(size_t i = 0; i < m; i++){
			const V2 a = v[i], b = v[(i + 1) % m];
			const V2 prev = v[(i + m - 1) % m], next = v[(i + 2) % m];
			lanes.push_back({std::fmin(a.x, b.x) - h, std::fmin(a.z, b.z) - h,
					std::fmax(a.x, b.x) + h, std::fmax(a.z, b.z) + h});
			auto dir = [](V2 p0, V2 p1){
				const float dx = p1.x - p0.x, dz = p1.z - p0.z,
						l = std::sqrt(dx * dx + dz * dz);
				return V2{dx / l, dz / l};
			};
			const V2 d = dir(a, b), din = dir(prev, a), dout = dir(b, next);
			for(int side = -1; side <= 1; side += 2){
				const V2 nm = {-d.z * side, d.x * side};
				// Toward the turn is its inside: short; away, its outside
				auto ext = [&](float toward){
					return std::fabs(toward) < 0.01f ? 0 : toward > 0 ? -h : h;
				};
				const float e0 = ext(-(nm.x * din.x + nm.z * din.z)),
						e1 = ext(nm.x * dout.x + nm.z * dout.z);
				f.push_back({a.x + nm.x * h - d.x * e0, a.z + nm.z * h - d.z * e0,
						b.x + nm.x * h + d.x * e1, b.z + nm.z * h + d.z * e1});
			}
		}
		// Two lanes side by side share one: the same line's overlapping
		// stretches made one
		for(Fence &a : f){
			if(a.x0 > a.x1 || a.z0 > a.z1){
				std::swap(a.x0, a.x1);
				std::swap(a.z0, a.z1);
			}
		}
		std::sort(f.begin(), f.end(), [](const Fence &a, const Fence &b){
			const bool ax = a.z0 == a.z1, bx = b.z0 == b.z1;
			if(ax != bx) return ax;
			const float ka = ax ? a.z0 : a.x0, kb = bx ? b.z0 : b.x0;
			if(std::fabs(ka - kb) > 0.01f) return ka < kb;
			return (ax ? a.x0 : a.z0) < (bx ? b.x0 : b.z0);
		});
		for(const Fence &a : f){
			if(!fences.empty()){
				Fence &l = fences.back();
				const bool ax = a.z0 == a.z1, lx = l.z0 == l.z1;
				if(ax == lx && std::fabs(ax ? a.z0 - l.z0 : a.x0 - l.x0) < 0.01f &&
						(ax ? a.x0 <= l.x1 + 0.01f : a.z0 <= l.z1 + 0.01f)){
					l.x1 = std::fmax(l.x1, a.x1);
					l.z1 = std::fmax(l.z1, a.z1);
					continue;
				}
			}
			fences.push_back(a);
		}
		// The reliefs, half a lane each way: where the triangle is off every
		// lane and in the area, it is track and its long side the fence;
		// where it is all lane already (a hairpin's tip, the fence between
		// the two ways the car may cross anyway), that fence is cut back
		const float leg = h;
		std::vector<V2> trimmed;
		for(size_t i = 1; i < m; i++){
			const V2 c0 = v[i], pv = v[i - 1], nx = v[(i + 1) % m];
			auto unit_of = [](V2 p0, V2 p1){
				const float dx = p1.x - p0.x, dz = p1.z - p0.z,
						l = std::sqrt(dx * dx + dz * dz);
				return V2{dx / l, dz / l};
			};
			const V2 din = unit_of(pv, c0), dout = unit_of(c0, nx);
			const Relief r = {{c0.x + (dout.x - din.x) * h, c0.z + (dout.z - din.z) * h},
					{-din.x, -din.z}, dout, leg, i};
			// Off every lane: a box in the triangle's own frame (its legs
			// are along X and Z) clear of a + b < leg; in the area: its
			// corners. All lane: every point a quarter voxel apart in one.
			bool fits = true;
			for(const Box &bx : lanes){
				auto along = [&](V2 d, float &lo, float &hi){
					const float p0 = (bx.x0 - r.c.x) * d.x + (bx.z0 - r.c.z) * d.z,
							p1 = (bx.x1 - r.c.x) * d.x + (bx.z1 - r.c.z) * d.z;
					lo = std::fmin(p0, p1), hi = std::fmax(p0, p1);
				};
				float a0, a1, b0, b1;
				along(r.a, a0, a1);
				along(r.b, b0, b1);
				fits = fits && !(a1 > 0.01f && b1 > 0.01f &&
						std::fmax(a0, 0.0f) + std::fmax(b0, 0.0f) < leg - 0.01f);
			}
			for(int k = 0; k < 3; k++){
				const float x = r.c.x + (k == 1 ? r.a.x : k == 2 ? r.b.x : 0) * leg,
						z = r.c.z + (k == 1 ? r.a.z : k == 2 ? r.b.z : 0) * leg;
				fits = fits && x >= -0.01f && x <= W + 0.01f && z >= -0.01f &&
						z <= Z + 0.01f;
			}
			// ... and off another corner's (two across a thin middle)
			bool tip = true;
			for(float a = 0.25f; a < leg; a += 0.25f)
			for(float b = 0.25f; a + b < leg; b += 0.25f){
				const float x = r.c.x + r.a.x * a + r.b.x * b,
						z = r.c.z + r.a.z * a + r.b.z * b;
				bool in = false;
				for(const Box &bx : lanes)
					in = in || (x > bx.x0 && x < bx.x1 && z > bx.z0 && z < bx.z1);
				tip = tip && in;
				for(const Relief &o : reliefs){
					const float oa = (x - o.c.x) * o.a.x + (z - o.c.z) * o.a.z,
							ob = (x - o.c.x) * o.b.x + (z - o.c.z) * o.b.z;
					fits = fits && !(oa > 0 && ob > 0 && oa + ob < o.leg);
				}
			}
			bool done = false;
			for(const V2 &t : trimmed)
				done = done || (std::fabs(t.x - r.c.x) < 0.01f &&
						std::fabs(t.z - r.c.z) < 0.01f);
			if(!(fits || tip) || done)
				continue;
			trimmed.push_back(r.c);
			if(tip && !fits && i + 2 < m){
				// The next turn's triangle from the same corner
				const V2 n2 = v[i + 2];
				const V2 d2 = unit_of(nx, n2);
				gaps.push_back({r, i, true});
				gaps.push_back({{r.c, {-dout.x, -dout.z}, d2, leg, i + 1}, i, false});
			}
			for(Fence &e : fences){
				for(int end = 0; end < 2; end++){
					float &ex = end ? e.x1 : e.x0, &ez = end ? e.z1 : e.z0;
					const float ox = end ? e.x0 : e.x1, oz = end ? e.z0 : e.z1;
					if(std::fabs(ex - r.c.x) > 0.01f || std::fabs(ez - r.c.z) > 0.01f)
						continue;
					const float l = std::fabs(ox - ex) + std::fabs(oz - ez);
					const float t = std::fmin(leg, l) / l;
					ex += (ox - ex) * t;
					ez += (oz - ez) * t;
				}
			}
			if(fits){
				reliefs.push_back(r);
				fences.push_back({r.c.x + r.a.x * leg, r.c.z + r.a.z * leg,
						r.c.x + r.b.x * leg, r.c.z + r.b.z * leg});
			}
		}
		// The ones a turn left with no length
		fences.erase(std::remove_if(fences.begin(), fences.end(),
				[](const Fence &e){
			return std::fabs(e.x1 - e.x0) + std::fabs(e.z1 - e.z0) < 0.01f;
		}), fences.end());
		// Into the voxels' frame
		for(Relief &r : reliefs)
			r.c.x -= 0.5f, r.c.z -= 0.5f;
		for(Gap &g : gaps)
			g.r.c.x -= 0.5f, g.r.c.z -= 0.5f;
		for(V2 &q : v)
			q.x -= 0.5f, q.z -= 0.5f;
		for(Box &b : lanes)
			b.x0 -= 0.5f, b.z0 -= 0.5f, b.x1 -= 0.5f, b.z1 -= 0.5f;
		for(Fence &e : fences)
			e.x0 -= 0.5f, e.z0 -= 0.5f, e.x1 -= 0.5f, e.z1 -= 0.5f;
		path = v;
	}
	// Whether (x, z) is in a lane, or with none (the straight hill) over the
	// area
	bool on_track(float x, float z) const
	{
		if(!p.circuit)
			return over(x, z);
		for(const Box &b : lanes)
			if(x >= b.x0 && x <= b.x1 && z >= b.z0 && z <= b.z1)
				return true;
		for(const Relief &r : reliefs){
			const float a = (x - r.c.x) * r.a.x + (z - r.c.z) * r.a.z,
					b = (x - r.c.x) * r.b.x + (z - r.c.z) * r.b.z;
			if(a >= 0 && b >= 0 && a + b <= r.leg)
				return true;
		}
		return false;
	}
	// [HC_HOLLOW_MIDDLE] Whether the column of sections (sx, sz), 64 voxels
	// a side, is all middle: no column of it, nor within two voxels of
	// it, on the track. Such a section is never loaded (main.cpp's pins);
	// the client draws the land there. A straight hill has none.
	static const int SECTION = 64;
	bool hollow_section(int sx, int sz) const
	{
		if(!p.circuit)
			return false;
		const int M = 2;
		for(int z = sz * SECTION - M; z < (sz + 1) * SECTION + M; z++)
			for(int x = sx * SECTION - M; x < (sx + 1) * SECTION + M; x++)
				if(on_track((float)x, (float)z))
					return false;
		return true;
	}
	// Where a car starts, in voxels and degrees about Y: the bottom pad's
	// middle facing up, or the circuit's start line 3 m ahead facing +X
	void start(float &x, float &z, float &yaw) const
	{
		if(!p.circuit){
			x = size_x() / 2.0f, z = PAD / 2.0f, yaw = 0;
			return;
		}
		x = path[0].x - 3 * U, z = path[0].z, yaw = 90;
	}
	// A lap: each turn passed in order -- in the square its two lanes
	// share, or in its inner corner's relief triangle where it has one
	// ([HC_BACKTRACK]: a turn with none was counted from the triangle its
	// relief would have, which can lie in the turn before's relief) -- or
	// in a hairpin's opening, then the start line
	// crossed toward +X in the bottom lane. A cut across a fence the lanes
	// share misses a turn; one backwards crosses the line the other way.
	struct Lap { size_t next = 1; int laps = 0; float x = 0; bool at = false; };
	bool lap_step(Lap &l, float x, float z) const
	{
		if(path.size() < 2)
			return false;
		bool lap = false;
		if(l.next < path.size()){
			const float h = lane / 2;
			const V2 v = path[l.next];
			bool in = std::fabs(x - v.x) <= h && std::fabs(z - v.z) <= h;
			for(const Relief &r : reliefs)
				in = in || (r.turn == l.next && in_relief(r, x, z));
			if(in)
				l.next++;
			else
				for(const Gap &g : gaps)
					if((l.next == g.n + 1 || (l.next == g.n && g.out)) &&
							in_relief(g.r, x, z))
						l.next = g.n + 2;
		}
		if(l.at && l.x < path[0].x && x >= path[0].x &&
				z < path[0].z + lane / 2 && l.next == path.size()){
			l.laps++;
			l.next = 1;
			lap = true;
		}
		l.x = x;
		l.at = true;
		return lap;
	}
	static bool in_relief(const Relief &r, float x, float z)
	{
		const float a = (x - r.c.x) * r.a.x + (z - r.c.z) * r.a.z,
				b = (x - r.c.x) * r.b.x + (z - r.c.z) * r.b.z;
		return a >= 0 && b >= 0 && a + b <= r.leg;
	}
	// Lane i (to turn i + 1), the start's straight the last
	bool in_lane(size_t i, float x, float z) const
	{
		if(lanes.empty())
			return false;
		const Box &b = lanes[i % lanes.size()];
		return x >= b.x0 && x <= b.x1 && z >= b.z0 && z <= b.z1;
	}
	// [HC_LAP_TURNS] Whether (x, z) is where a car on lap l may be: the
	// lane to its next turn and every lane the lap has driven before it
	// ([HC_BACKTRACK]: backing up past a passed turn is no miss; the turn
	// stays passed and the next is still to pass), before the first turn
	// the start's straight behind the line too, and the reliefs and
	// openings of the turns up to the next. Elsewhere on the track, it
	// crossed a fence two lanes share: past a turn it did not pass
	// ([HC_MISSED_TURN_MARK]: the lane after the next turn is not allowed,
	// so a skip is seen at that turn)
	bool in_lap_lanes(const Lap &l, float x, float z) const
	{
		const size_t m = lanes.size();
		if(m == 0)
			return true;
		for(size_t i = 0; i < l.next && i < m; i++)
			if(in_lane(i, x, z))
				return true;
		if(l.next == 1 && in_lane(m - 1, x, z))
			return true;
		for(const Relief &r : reliefs)
			if(r.turn <= l.next && in_relief(r, x, z))
				return true;
		// A hairpin's opening from before its first turn on
		for(const Gap &g : gaps)
			if(l.next >= g.n && in_relief(g.r, x, z))
				return true;
		return false;
	}
	// Turn n's square, the two lanes' shared one
	Box turn_square(size_t n) const
	{
		const V2 v = path[n % path.size()];
		return {v.x - lane / 2, v.z - lane / 2, v.x + lane / 2, v.z + lane / 2};
	}

	// [HC_STEEP_NOISE] n(x, z) in -1..1: value noise, stretched by 1.5 so
	// that its extremes are reached, and clamped
	float steep_noise(float x, float z) const
	{
		const float n = 1.5f * noise(x, z, VAR_CELL, 3);
		return n < -1 ? -1 : n > 1 ? 1 : n;
	}
	// The local angle's tangent at (x, z) on the slope's middle
	float local_k(float x, float z) const
	{
		return std::tan((p.steep_deg + p.steep_var_deg * steep_noise(x, z)) *
				PI / 180);
	}
	// The profile tables: the rate, the even slope's eased one with k the
	// local angle's, summed along z by the midpoint of each voxel
	void vary()
	{
		const int nz = size_z() + 1;
		prof.assign((size_t)track_w * nz, 0);
		rise = 0;
		for(int x = 0; x < track_w; x++){
			float h = 0;
			for(int z = 0; z < nz; z++){
				prof[(size_t)x * nz + z] = h;
				const float u = z + 0.5f - PAD;
				float ease = u <= 0 || u >= run ? 0 : u < EASE ? u / EASE :
						u > run - EASE ? (run - u) / EASE : 1;
				h += ease * local_k((float)x, z + 0.5f);
			}
			rise = std::max(rise, h);
		}
	}

	int size_x() const { return track_w; }
	int size_z() const { return 2 * PAD + run; }
	int size_y() const { return BASE + (int)std::ceil(rise) + BUMP + 8; }
	// Where the slope starts and where the top pad does, along Z
	int slope_z0() const { return PAD; }
	int top_z0() const { return PAD + run; }
	// The surface's height over the bottom pad at z, unbumped: the slope's
	// rise integrated, its rate easing from 0 to k over EASE at each end
	// [HC_STEEP_NOISE] At column x: with a variance from the tables,
	// interpolated between their columns and rows; with none the same for
	// every x
	float profile(float x, float z) const
	{
		if(!prof.empty()){
			const int nz = size_z() + 1;
			const float cx = std::fmin(std::fmax(x, 0.0f), track_w - 1.0f),
					cz = std::fmin(std::fmax(z, 0.0f), (float)(nz - 1));
			const int x0 = std::max(0, std::min((int)cx, track_w - 2)),
					z0 = std::min((int)cz, nz - 2);
			const float tx = cx - x0, tz = cz - z0;
			auto at = [&](int a, int b){ return prof[(size_t)a * nz + b]; };
			const float a = at(x0, z0) + (at(x0, z0 + 1) - at(x0, z0)) * tz,
					b = at(x0 + 1, z0) + (at(x0 + 1, z0 + 1) - at(x0 + 1, z0)) * tz;
			return a + (b - a) * tx;
		}
		float u = z - PAD;
		if(u <= 0)
			return 0;
		if(u >= run)
			return rise;
		const float e = EASE;
		if(u < e)
			return k * u * u / (2 * e);
		if(u > run - e){
			float v = run - u;
			return rise - k * v * v / (2 * e);
		}
		return k * e / 2 + k * (u - e);
	}

	static uint32_t hash(uint32_t a, uint32_t b, uint32_t c, uint32_t d)
	{
		uint32_t h = a * 0x9e3779b1u ^ b * 0x85ebca77u ^ c * 0xc2b2ae3du ^
				d * 0x27d4eb2fu;
		h ^= h >> 15; h *= 0x2c1b3c6du; h ^= h >> 12; h *= 0x297a2d39u;
		return h ^ (h >> 15);
	}
	float unit(uint32_t a, uint32_t b, uint32_t c, uint32_t d) const
	{
		return (hash(a, b, c, d ^ p.seed) & 0xffffff) / (float)0x1000000;
	}
	// [HC_ENGINE_NOISE] The engine's value noise, -1..1, cells of `cell`
	// voxels; salt 1 to 3 (seed * 4 + salt: no two seeds' salts the same)
	float noise(float x, float z, int cell, uint32_t salt) const
	{
		return interface::noise::value2(x / cell, z / cell, p.seed * 4 + salt);
	}
	// The widest free run across the track at row z, voxels
	int free_width(const std::vector<Feature> &fs, int z) const
	{
		std::vector<std::pair<float, float>> blocked;
		for(const Feature &f : fs){
			float dz = z + 0.5f - f.z;
			if(dz * dz < f.r * f.r){
				float h = std::sqrt(f.r * f.r - dz * dz);
				blocked.push_back({f.x - h, f.x + h});
			}
		}
		std::sort(blocked.begin(), blocked.end());
		float at = 0, best = 0;
		for(auto &b : blocked){
			best = std::max(best, b.first - at);
			at = std::max(at, b.second);
		}
		best = std::max(best, (float)track_w - at);
		return (int)std::floor(best);
	}
	// The features from the seed: a slot each FEATURE_EVERY along the
	// slope (off the pads and the eased ends, TOP_CLEAR from the top), a
	// pit or a rock at random in it, left out where it would touch
	// another or close a row to under FREE_W.
	// [HC_CIRCUIT] As many to the area as on the straight hill, each
	// inside a lane leaving FREE_W of it beside, a lane from a turn's
	// corner and FREE_W from another
	bool in_lane(const Feature &f) const
	{
		if(lane - 2 * f.r < FREE_W)
			return false;
		for(const V2 &q : path){
			const float dx = f.x - 0.5f - q.x, dz = f.z - 0.5f - q.z;
			if(dx * dx + dz * dz < lane * lane)
				return false;
		}
		for(const Box &b : lanes)
			if(f.x - 0.5f - f.r >= b.x0 && f.x - 0.5f + f.r <= b.x1 &&
					f.z - 0.5f - f.r >= b.z0 && f.z - 0.5f + f.r <= b.z1)
				return true;
		return false;
	}
	void place_features()
	{
		const float lo = PAD + EASE, hi = top_z0() - TOP_CLEAR;
		const int n = (int)((hi - lo) / FEATURE_EVERY * track_w / TRACK_W);
		for(int i = 0; i < n; i++){
			Feature f;
			f.kind = unit(i, 0, 0, 101) < 0.5f ? PIT : ROCK;
			// A pit 1 to 2.5 m across and 0.3 to 0.7 m deep; a rock 0.4 to
			// 0.9 m in radius
			f.r = f.kind == PIT ? (0.5f + 0.75f * unit(i, 1, 0, 101)) * U :
					(0.4f + 0.5f * unit(i, 1, 0, 101)) * U;
			f.depth = (0.3f + 0.4f * unit(i, 2, 0, 101)) * U;
			f.z = lo + f.r + (i + unit(i, 3, 0, 101)) * (hi - lo - 2 * f.r) / n;
			f.x = f.r + unit(i, 4, 0, 101) * (track_w - 2 * f.r);
			f.y = 0;
			bool ok = f.z + f.r <= hi && (!p.circuit || in_lane(f));
			const float apart = p.circuit ? FREE_W : U;
			for(const Feature &g : features){
				float dx = f.x - g.x, dz = f.z - g.z;
				ok = ok && dx * dx + dz * dz > (f.r + g.r + apart) *
						(f.r + g.r + apart);
			}
			std::vector<Feature> with = features;
			with.push_back(f);
			for(int z = (int)(f.z - f.r); ok && !p.circuit && z <= (int)(f.z + f.r);
					z++)
				ok = free_width(with, z) >= FREE_W;
			if(!ok)
				continue;
			if(f.kind == ROCK){
				// A third to a half of it over the sand
				float above = (2.0f / 3 + 1.0f / 3 * unit(i, 5, 0, 101)) * f.r;
				f.y = surface((int)f.x, (int)f.z) + 1 + above - f.r;
			}
			features.push_back(f);
		}
	}
	// How far the pits lower the surface at (x, z): a bowl at the sand's
	// angle of repose, flat at its depth
	float pit_depth(float x, float z) const
	{
		float d = 0;
		for(const Feature &f : features){
			if(f.kind != PIT)
				continue;
			float dx = x - f.x, dz = z - f.z, r = std::sqrt(dx * dx + dz * dz);
			if(r < f.r)
				d = std::max(d, std::fmin(f.depth, (f.r - r) * REPOSE));
		}
		return d;
	}
	const Feature *rock_at(int x, int y, int z) const
	{
		for(const Feature &f : features){
			float qx = x + 0.5f - f.x, qy = y + 0.5f - f.y, qz = z + 0.5f - f.z;
			if(f.kind == ROCK && qx * qx + qy * qy + qz * qz <= f.r * f.r)
				return &f;
		}
		return nullptr;
	}

	// The surface's height before it is cut to voxels, at a column (x, z)
	// or between them. The pads are flat; the slope undulates by up to
	// BUMP, faded in from its ends, and dips into the pits
	float height(float x, float z) const
	{
		float h = BASE + profile(x, z + 0.5f);
		float u = (z + 0.5f - PAD) / (float)EASE;
		float w = u <= 0 ? 0 : u >= 1 ? 1 : u;
		float v = (top_z0() - z - 0.5f) / (float)EASE;
		w *= v <= 0 ? 0 : v >= 1 ? 1 : v;
		h += w * BUMP * noise(x, z, 3 * U, 1);
		h -= pit_depth(x + 0.5f, z + 0.5f);
		return h;
	}
	// The track's surface: the top voxel's y at (x, z)
	int surface(int x, int z) const
	{
		return (int)std::floor(height((float)x, (float)z));
	}
	// [HC_OPEN_EDGES] Whether (x, z) is over the voxel area (a voxel's
	// centre at its integer position: the area is -0.5 to size - 0.5)
	bool over(float x, float z) const
	{
		return x >= -0.5f && x <= size_x() - 0.5f && z >= -0.5f &&
				z <= size_z() - 0.5f;
	}
	// The ground outside the voxel area: its top's y at (x, z) (a voxel's
	// top face is its y + 0.5). The nearest edge column's height carried
	// out, so the slope's profile goes on sideways and the pads past the
	// ends, falling away gently with the distance d and given a slow noise
	// up to 2 m that grows over the first 20 m: flush with the voxels at
	// the edge, within a voxel. Inside the area, the edge's at that point.
	float outside(float x, float z) const
	{
		const float cx = std::fmin(std::fmax(x, 0.0f), size_x() - 1.0f);
		const float cz = std::fmin(std::fmax(z, 0.0f), size_z() - 1.0f);
		const float dx = x - cx, dz = z - cz;
		const float d = std::sqrt(dx * dx + dz * dz);
		const float fall = 0.15f * d * d / (d + 16.0f * U);
		const float amp = std::fmin(1.0f, d / (20.0f * U)) * 2 * U;
		return height(cx, cz) + 0.5f - fall + amp * noise(x, z, 30 * U, 2);
	}
	// A pebble: in a 4-voxel cell, a stone of radius 1..1.6 voxels about a
	// point in it, one cell in five. pebble_of() says which: its centre in
	// voxel coordinates (a voxel's centre is its integer position) and its
	// radius, for the ground to loosen it whole ([HILLCLIMB] 4).
	// A rock ([HC_PITS_ROCKS]) is one too, whole: the ground loosens it by
	// its bed, which a big one's weight holds.
	bool pebble_of(int x, int y, int z, float &ox, float &oy, float &oz,
			float &radius) const
	{
		if(const Feature *f = rock_at(x, y, z)){
			ox = f->x - 0.5f;
			oy = f->y - 0.5f;
			oz = f->z - 0.5f;
			radius = f->r;
			return true;
		}
		const int C = 4;
		int cx = (int)std::floor(x / (float)C), cy = (int)std::floor(y / (float)C),
				cz = (int)std::floor(z / (float)C);
		for(int dz = -1; dz <= 1; dz++)
		for(int dy = -1; dy <= 1; dy++)
		for(int dx = -1; dx <= 1; dx++){
			int a = cx + dx, b = cy + dy, c = cz + dz;
			if(unit(a, b, c, 7) >= 0.2f)
				continue;
			float px = (a + unit(a, b, c, 11)) * C, py = (b + unit(a, b, c, 13)) * C,
					pz = (c + unit(a, b, c, 17)) * C;
			float r = 1.0f + 0.6f * unit(a, b, c, 19);
			float qx = x + 0.5f - px, qy = y + 0.5f - py, qz = z + 0.5f - pz;
			if(qx * qx + qy * qy + qz * qz <= r * r){
				ox = px - 0.5f;
				oy = py - 0.5f;
				oz = pz - 0.5f;
				radius = r;
				return true;
			}
		}
		return false;
	}
	bool pebble(int x, int y, int z) const
	{
		float a, b, c, r;
		return pebble_of(x, y, z, a, b, c, r);
	}

	Voxel at(int x, int y, int z) const
	{
		if(x < 0 || x >= size_x() || z < 0 || z >= size_z() || y < 0)
			return AIR;
		const int s = surface(x, z);
		if(y > s)
			return rock_at(x, y, z) ? STONE : AIR;
		if(y <= s - SHELL)
			return FILL;
		if(pebble(x, y, z))
			return STONE;
		return y > s - p.loose ? SAND : WET;
	}
};

} // namespace hill

#ifdef HILL_TEST
#include <cassert>
#include <cstdio>
#include <cstdlib>
int main(int argc, char **argv)
{
	using namespace hill;
	// "hill_test <seed> <steep> <length>": that hill's features, in metres
	// (x across from the left bank's outside, z up from the bottom)
	if(argc == 4){
		Params fp;
		fp.seed = (uint32_t)atoi(argv[1]);
		fp.steep_deg = (float)atof(argv[2]);
		fp.length_m = (float)atof(argv[3]);
		Hill h(fp);
		for(const Hill::Feature &f : h.features)
			printf("%s %.2f %.2f %.2f\n", f.kind == Hill::PIT ? "pit" : "rock",
					f.x / U, f.z / U, f.r / U);
		return 0;
	}
	Params p;
	Hill a(p), b(p);
	// The same seed, the same hill; another seed, another
	Params q = p; q.seed = 2;
	Hill c(q);
	int same = 0, differ = 0;
	for(int z = 0; z < a.size_z(); z += 3)
	for(int y = 0; y < a.size_y(); y += 2)
	for(int x = 0; x < a.size_x(); x += 3){
		same += a.at(x, y, z) == b.at(x, y, z);
		differ += a.at(x, y, z) != c.at(x, y, z);
		assert(a.at(x, y, z) == b.at(x, y, z));
	}
	assert(differ > 0);
	// The slope within a few degrees of the asked one along its middle,
	// measured over each 4 m
	for(int z = a.slope_z0() + Hill::EASE; z + 4 * U <=
			a.top_z0() - Hill::EASE; z += 4 * U){
		float m = 0;
		for(int x = 0; x < Hill::TRACK_W; x++)
			m += a.surface(x, z + 4 * U) - a.surface(x, z);
		m /= Hill::TRACK_W * 4.0f * U;
		float deg = std::atan(m) * 180 / PI;
		assert(std::fabs(deg - p.steep_deg) < 3);
	}
	// The pads flat and as long as the car (2.8 m wheelbase, 0.8 m tyres)
	for(int x = 0; x < Hill::TRACK_W; x++){
		for(int z = 0; z < Hill::PAD; z++)
			assert(a.surface(x, z) == Hill::BASE);
		int top = a.surface(x, a.top_z0());
		for(int z = a.top_z0(); z < a.size_z(); z++)
			assert(a.surface(x, z) == top);
	}
	assert(Hill::PAD >= (int)(3.6f * U));
	// [HC_OPEN_EDGES] 10 m of track, the area's whole width, sand on top
	// with stones in it to every edge
	assert(Hill::TRACK_W == 10 * U && a.size_x() == Hill::TRACK_W);
	int sand = 0, stone = 0;
	for(int z = 0; z < a.size_z(); z++)
	for(int x = 0; x < Hill::TRACK_W; x++){
		int s = a.surface(x, z);
		assert(a.at(x, s + 1, z) == AIR || a.rock_at(x, s + 1, z));
		assert(a.at(x, s, z) != AIR && a.at(x, s, z) != FILL);
		for(int y = s - Hill::SHELL + 1; y <= s; y++){
			const Voxel v = a.at(x, y, z);
			sand += v == SAND || v == WET;
			stone += v == STONE;
			// [HC_WET_SAND] Loose over the top p.loose, wet under it
			assert(v == STONE || v == (y > s - p.loose ? SAND : WET));
		}
		assert(a.at(x, s - Hill::SHELL, z) == FILL);
	}
	assert(stone > sand / 50 && stone < sand / 2);
	// [HC_WET_SAND] No loose layer: wet to the top; all of it, no wet
	{
		Params w = p;
		w.loose = 0;
		Hill d(w);
		const int x = 40, z = d.size_z() / 2, s = d.surface(x, z);
		for(int y = s - Hill::SHELL + 1; y <= s; y++)
			assert(d.at(x, y, z) == STONE || d.at(x, y, z) == WET);
		w.loose = Hill::SHELL;
		Hill e(w);
		for(int y = s - Hill::SHELL + 1; y <= s; y++)
			assert(e.at(x, y, z) == STONE || e.at(x, y, z) == SAND);
	}
	// The car's start (main.cpp: the pad's middle) on the pad: the rear
	// tyre's back 1.4 + 0.4 m behind it
	assert(Hill::PAD / 2 - (int)std::ceil(1.8f * U) >= 0);
	// [HC_OPEN_EDGES] The ground outside flush with every edge column's
	// top (its top face, y + 0.5) within a voxel, half a voxel out; lower
	// far off, and over the slope's middle sideways higher than the pad
	float worst = 0;
	auto flush = [&](int x, int z, float ox, float oz){
		const float o = a.outside(ox, oz), top = a.surface(x, z) + 0.5f;
		worst = std::fmax(worst, std::fabs(o - top));
		// A voxel, and the noise's few hundredths half a voxel out
		if(std::fabs(o - top) > 1.1f)
			fprintf(stderr, "not flush at %d,%d: %.2f, the top %.2f\n", x, z, o, top);
		assert(std::fabs(o - top) <= 1.1f);
	};
	for(int z = 0; z < a.size_z(); z++){
		flush(0, z, -0.5f, (float)z);
		flush(a.size_x() - 1, z, a.size_x() - 0.5f, (float)z);
	}
	for(int x = 0; x < a.size_x(); x++){
		flush(x, 0, (float)x, -0.5f);
		flush(x, a.size_z() - 1, (float)x, a.size_z() - 0.5f);
	}
	const float mid = a.slope_z0() + a.run / 2.0f;
	assert(a.outside(-20 * U, mid) > Hill::BASE + a.rise / 4);
	assert(a.outside(-150 * U, mid) < a.outside(-0.5f, mid) - 10 * U);
	assert(a.outside(a.size_x() / 2.0f, -100 * U) < Hill::BASE);
	assert(!a.over(-0.6f, 10) && a.over(-0.4f, 10) && !a.over(10, a.size_z()));
	// [HC_PITS_ROCKS] Over 50 seeds at the default 29 degrees: a row of
	// the track never under 3 m free; nothing on the pads, the eased ends
	// or the last 4 m; a pit's dip 0.3 to 0.7 m; a third to a half of a
	// rock over the sand; a rock is a stone the ground loosens whole
	int pits = 0, rocks = 0;
	for(uint32_t seed = 1; seed <= 50; seed++){
		Params fp;
		fp.seed = seed;
		fp.steep_deg = 29;
		Hill h(fp);
		Hill same(fp);
		assert(same.features.size() == h.features.size());
		for(int z = 0; z < h.size_z(); z++)
			assert(h.free_width(h.features, z) >= Hill::FREE_W);
		for(const Hill::Feature &f : h.features){
			assert(f.z - f.r >= Hill::PAD + Hill::EASE);
			assert(f.z + f.r <= h.top_z0() - Hill::TOP_CLEAR);
			assert(f.x - f.r >= 0 && f.x + f.r <= Hill::TRACK_W);
			if(f.kind == Hill::PIT){
				pits++;
				float dip = h.pit_depth(f.x, f.z);
				assert(dip >= 0.3f * U - 0.01f && dip <= 0.7f * U + 0.01f);
			} else {
				rocks++;
				float top = f.y + f.r, sand = h.surface((int)f.x, (int)f.z) + 1;
				assert(top - sand >= 2 * f.r / 3 - 0.01f && top - sand <= f.r + 0.01f);
				int cx = (int)f.x, cz = (int)f.z;
				assert(h.at(cx, (int)(f.y + f.r - 1), cz) == STONE);
				float ox, oy, oz, r;
				assert(h.pebble_of(cx, (int)f.y, cz, ox, oy, oz, r) && r == f.r);
			}
		}
	}
	assert(pits > 50 && rocks > 50);
	// [HC_STEEP_NOISE] 27 degrees varied by 4: the local angle along the
	// slope's middle (the profile's, under the bump) within 27 +- 4 and
	// spread over most of it; the same seed the same ground; each column's
	// top pad flat at its own height
	Params vp;
	vp.steep_deg = 27, vp.steep_var_deg = 4, vp.features = false;
	const Hill v(vp), v2(vp);
	float lo = 90, hi = 0;
	for(int x = 0; x < Hill::TRACK_W; x++)
	for(int z = v.slope_z0() + Hill::EASE; z < v.top_z0() - Hill::EASE; z++){
		const float deg = std::atan(v.profile((float)x, z + 1.0f) -
				v.profile((float)x, (float)z)) * 180 / PI;
		assert(deg >= 23 - 0.01f && deg <= 31 + 0.01f);
		lo = std::fmin(lo, deg), hi = std::fmax(hi, deg);
		assert(v.surface(x, z) == v2.surface(x, z));
	}
	assert(lo < 24 && hi > 30);
	for(int x = 0; x < Hill::TRACK_W; x++)
	for(int z = v.top_z0(); z < v.size_z(); z++)
		assert(v.surface(x, z) == v.surface(x, v.top_z0()));
	assert(v.size_y() > v.surface(0, v.top_z0()) && v.rise > 0);
	printf("hill.h: 27 degrees varied by 4: local angles %.1f to %.1f\n", lo, hi);
	// [HC_CIRCUIT] 48 m wide, 30 m of slope: at lanes of 4, 6 and 8 m and
	// switchbacks at 0, 50 and 100%, the loop inside the area, no two
	// lanes but neighbours overlapping (so it does not cross itself and
	// each lane is its width), the middle (the area off the lanes) shrinking
	// as the switchbacks grow; each drawn from above into argv[1]'s
	// directory, if given, as circuit_<lane>_<switchbacks>.pgm (lanes grey,
	// fences black, the middle white, the turns' corners dark grey)
	auto middle = [](const Hill &c){
		int off = 0;
		for(int z = 0; z < c.size_z(); z++)
		for(int x = 0; x < c.size_x(); x++)
			off += !c.on_track((float)x, (float)z);
		return off;
	};
	auto check_path = [](const Hill &c){
		const size_t m = c.lanes.size();
		assert(m == c.path.size() && m >= 4);
		for(size_t i = 0; i < m; i++){
			const Hill::Box &a = c.lanes[i];
			assert(a.x0 >= -0.51f && a.z0 >= -0.51f && a.x1 <= c.size_x() - 0.49f &&
					a.z1 <= c.size_z() - 0.49f);
			assert(std::fabs(std::fmin(a.x1 - a.x0, a.z1 - a.z0) - c.lane) < 0.01f);
			for(size_t j = i + 2; j < m; j++){
				if(i == 0 && j == m - 1)
					continue;
				const Hill::Box &b = c.lanes[j];
				const float ox = std::fmin(a.x1, b.x1) - std::fmax(a.x0, b.x0),
						oz = std::fmin(a.z1, b.z1) - std::fmax(a.z0, b.z0);
				if(ox > 0.01f && oz > 0.01f)
					fprintf(stderr, "lanes %zu and %zu overlap\n", i, j);
				assert(!(ox > 0.01f && oz > 0.01f));
			}
		}
		// No fence through a lane: a fence is on lanes' edges only
		for(const Hill::Fence &f : c.fences){
			const float len = std::fabs(f.x1 - f.x0) + std::fabs(f.z1 - f.z0);
			for(float t = 0; t <= len; t += 1){
				const float x = f.x0 + (f.x1 - f.x0) * t / len,
						z = f.z0 + (f.z1 - f.z0) * t / len;
				for(const Hill::Box &b : c.lanes)
					assert(!(x > b.x0 + 0.01f && x < b.x1 - 0.01f &&
							z > b.z0 + 0.01f && z < b.z1 - 0.01f));
			}
		}
	};
	for(float lane_m : {4.0f, 6.0f, 8.0f}){
		int prev = 1 << 30, at0 = 0, at100 = 0;
		size_t turns0 = 0, turns100 = 0;
		for(int sw : {0, 50, 100}){
			Params cp;
			cp.circuit = true, cp.width_m = 48, cp.lane_m = lane_m;
			cp.length_m = 30, cp.switchbacks = sw, cp.steep_deg = 18;
			cp.features = false;
			const Hill c(cp);
			check_path(c);
			const int mid = middle(c);
			assert(mid <= prev);
			prev = mid;
			(sw == 0 ? at0 : at100) = mid;
			(sw == 0 ? turns0 : turns100) = c.path.size();
			if(argc == 2){
				char name[256];
				snprintf(name, sizeof name, "%s/circuit_%.0f_%d.pgm", argv[1],
						lane_m, sw);
				FILE *f = fopen(name, "wb");
				assert(f);
				fprintf(f, "P5 %d %d 255\n", c.size_x(), c.size_z());
				std::vector<unsigned char> px((size_t)c.size_x() * c.size_z());
				for(int z = 0; z < c.size_z(); z++)
				for(int x = 0; x < c.size_x(); x++)
					px[(size_t)(c.size_z() - 1 - z) * c.size_x() + x] =
							c.on_track((float)x, (float)z) ? 160 : 255;
				auto dot = [&](float x, float z, unsigned char v){
					const int ix = std::min(c.size_x() - 1, std::max(0, (int)std::lround(x))),
							iz = std::min(c.size_z() - 1, std::max(0, (int)std::lround(z)));
					if(ix >= 0 && ix < c.size_x() && iz >= 0 && iz < c.size_z())
						px[(size_t)(c.size_z() - 1 - iz) * c.size_x() + ix] = v;
				};
				for(const Hill::Fence &e : c.fences){
					const float len = std::fabs(e.x1 - e.x0) + std::fabs(e.z1 - e.z0);
					for(float t = 0; t <= len; t += 0.5f)
						dot(e.x0 + (e.x1 - e.x0) * t / len, e.z0 + (e.z1 - e.z0) *
								t / len, 0);
				}
				for(const Hill::V2 &q : c.path)
					for(int d = -2; d <= 2; d++)
						dot(q.x + d, q.z, 80), dot(q.x, q.z + d, 80);
				fwrite(px.data(), 1, px.size(), f);
				fclose(f);
			}
			printf("hill.h: circuit 48 m, lanes %.0f m, switchbacks %d%%: %zu "
					"turns, %zu fences, the middle %.0f m2\n", lane_m, sw,
					c.path.size() - 1, c.fences.size(), mid / (float)(U * U));
		}
		assert(at100 < at0 && turns100 > turns0);
	}
	// The plain loop: the area's edge and the middle's, eight fences
	Params pl;
	pl.circuit = true, pl.switchbacks = 0, pl.features = false;
	const Hill loop(pl);
	// The plain loop's four inner corners relieved: a diagonal each
	assert(loop.fences.size() == 12 && loop.path.size() == 5 &&
			loop.reliefs.size() == 4);
	{
		const Hill::Relief &r = loop.reliefs[0];
		const float x = r.c.x + (r.a.x + r.b.x) * r.leg / 4,
				z = r.c.z + (r.a.z + r.b.z) * r.leg / 4;
		assert(loop.on_track(x, z));
		assert(!loop.on_track(x + (r.a.x + r.b.x) * r.leg,
				z + (r.a.z + r.b.z) * r.leg));
	}
	assert(!loop.on_track(loop.size_x() / 2.0f, loop.size_z() / 2.0f));
	assert(loop.on_track(loop.path[0].x, loop.path[0].z));
	// [HC_HOLLOW_MIDDLE] A 60 m circuit of 6 m lanes at 0%: its middle's
	// whole sections hollow, every section a lane touches kept
	{
		Params hp;
		hp.circuit = true, hp.switchbacks = 0, hp.features = false;
		hp.width_m = 60, hp.lane_m = 6, hp.length_m = 60;
		const Hill h(hp);
		const int S = Hill::SECTION;
		int hollow = 0, kept = 0;
		for(int sz = 0; sz <= (h.size_z() - 1) / S; sz++)
			for(int sx = 0; sx <= (h.size_x() - 1) / S; sx++){
				bool lane = false;
				for(int z = sz * S; z < (sz + 1) * S && !lane; z++)
					for(int x = sx * S; x < (sx + 1) * S && !lane; x++)
						lane = h.on_track((float)x, (float)z);
				const bool hs = h.hollow_section(sx, sz);
				assert(!(lane && hs));
				hollow += hs, kept += !hs;
			}
		// 60 m is 480 voxels, 7.5 sections; lanes of 48 voxels round it
		assert(hollow >= 4 * 4 && kept > 0);
		assert(!loop.hollow_section(0, 0));
	}
	// The default circuit: 40 m, 7 m lanes, 50%: hairpins each way. Laps
	// by its centre line: two laps driven, two counted; backwards none; the
	// way up's hairpin cut across the fence it shares, none
	Params dp;
	dp.circuit = true, dp.steep_deg = 18, dp.steep_var_deg = 4, dp.length_m = 40;
	const Hill d(dp);
	check_path(d);
	assert(d.size_x() == 40 * U && d.path.size() > 5);
	// [HC_LAP_TURNS] crossed: the steps out of the lap's lanes
	int crossed = 0;
	auto drive = [&](const std::vector<Hill::V2> &pts, int loops){
		Hill::Lap l;
		crossed = 0;
		float sx, sz, yaw;
		d.start(sx, sz, yaw);
		Hill::V2 at = {sx, sz};
		std::vector<Hill::V2> route;
		for(int k = 0; k < loops; k++)
			for(const Hill::V2 &q : pts)
				route.push_back(q);
		route.push_back(pts[0]);
		for(const Hill::V2 &q : route){
			const float dx = q.x - at.x, dz = q.z - at.z;
			const int n = (int)(std::sqrt(dx * dx + dz * dz) / 2) + 1;
			for(int i = 1; i <= n; i++){
				const float x = at.x + dx * i / n, z = at.z + dz * i / n;
				d.lap_step(l, x, z);
				// (off the track is the put-back's own)
				crossed += d.on_track(x, z) && !d.in_lap_lanes(l, x, z);
			}
			at = q;
		}
		return l.laps;
	};
	assert(drive(d.path, 2) == 2 && crossed == 0);
	// A relief's middle is in the lap's lanes before its turn and after
	assert(!d.reliefs.empty());
	for(const Hill::Relief &r : d.reliefs){
		const float x = r.c.x + (r.a.x + r.b.x) * r.leg / 3,
				z = r.c.z + (r.a.z + r.b.z) * r.leg / 3;
		Hill::Lap l;
		l.next = r.turn;
		assert(d.in_lap_lanes(l, x, z));
		l.next = r.turn + 1;
		assert(d.in_lap_lanes(l, x, z));
		// [HC_BACKTRACK] Still the lap's once passed; not before its turn
		// is the next
		l.next = r.turn + 2;
		assert(d.in_lap_lanes(l, x, z));
		l.next = r.turn - 1;
		assert(r.turn < 2 || !d.in_lap_lanes(l, x, z));
	}
	// [HC_BACKTRACK] Backing up from the lane to the next turn into the
	// two lanes before it: the lap's lanes, the next turn still the next
	for(size_t k = 3; k < d.path.size(); k++){
		Hill::Lap l;
		l.next = k;
		for(size_t j = k - 2; j + 3 >= k; j--){
			const Hill::V2 p0 = d.path[j], p1 = d.path[j + 1];
			assert(d.in_lap_lanes(l, (p0.x + p1.x) / 2, (p0.z + p1.z) / 2));
			d.lap_step(l, (p0.x + p1.x) / 2, (p0.z + p1.z) / 2);
			assert(l.next == k);
		}
	}
	// The user's run (2026-10-20, 17:35:13): turn 8 with no relief, its
	// triangle in turn 7's: the car there with turn 8 next does not pass it
	{
		bool relief8 = false;
		for(const Hill::Relief &r : d.reliefs)
			relief8 = relief8 || r.turn == 8;
		Hill::Lap l;
		l.next = 8;
		d.lap_step(l, 7.15f * U, 43.37f * U);
		assert(relief8 || l.next == 8);
	}
	// [HC_MISSED_TURN_MARK] The lane after the next turn is out of the
	// lap's lanes (a connector a lane long ends on the lane before's box)
	for(size_t k = 1; k + 1 < d.path.size(); k++){
		const Hill::V2 p0 = d.path[k], p1 = d.path[k + 1];
		if(std::fabs(p1.x - p0.x) + std::fabs(p1.z - p0.z) <= d.lane + 0.01f)
			continue;
		Hill::Lap l;
		l.next = k;
		assert(!d.in_lap_lanes(l, (p0.x + p1.x) / 2, (p0.z + p1.z) / 2));
	}
	// Each hairpin's opening: the user's line, from the way in through the
	// open fence's gap into the way out, passes both turns, never out of
	// the lap's lanes (2026-10-20's runs: turns 3-4 at x 27-30 m)
	assert(d.gaps.size() == 4);
	for(size_t g = 0; g < d.gaps.size(); g += 2){
		const size_t n = d.gaps[g].n;
		assert(d.gaps[g].out && !d.gaps[g + 1].out && d.gaps[g + 1].n == n);
		auto mid = [&](const Hill::Relief &r){
			return Hill::V2{r.c.x + (r.a.x + r.b.x) * r.leg / 3,
					r.c.z + (r.a.z + r.b.z) * r.leg / 3};
		};
		const Hill::V2 in = mid(d.gaps[g + 1].r), out = mid(d.gaps[g].r);
		// In the ways in and out, not the turns' squares
		assert(d.in_lane(n - 1, in.x, in.z) && d.in_lane(n + 1, out.x, out.z));
		const Hill::Box sq = d.turn_square(n);
		assert(in.x < sq.x0 || in.x > sq.x1 || in.z < sq.z0 || in.z > sq.z1);
		Hill::Lap l;
		l.next = n;
		const Hill::V2 pts[] = {d.path[n - 1], in, out, d.path[n + 2]};
		for(int i = 0; i + 1 < 4; i++)
			for(int j = 1; j <= 40; j++){
				const float x = pts[i].x + (pts[i + 1].x - pts[i].x) * j / 40,
						z = pts[i].z + (pts[i + 1].z - pts[i].z) * j / 40;
				d.lap_step(l, x, z);
				assert(d.in_lap_lanes(l, x, z));
			}
		assert(l.next == n + 3);
	}
	std::vector<Hill::V2> back(d.path.rbegin(), d.path.rend());
	back.insert(back.begin(), d.path[0]);
	assert(drive(back, 2) == 0);
	std::vector<Hill::V2> cut;
	for(size_t i = 0; i < d.path.size(); i++)
		if(!(i >= 2 && i <= 5))  // the way up's hairpin: its four turns
			cut.push_back(d.path[i]);
	assert(d.path[2].x == d.path[1].x && d.path[5].x == d.path[1].x);
	assert(drive(cut, 2) == 0 && crossed > 0);
	// [HC_CIRCUIT] Pits and rocks over 20 seeds, each in a lane
	int in_lanes = 0;
	for(uint32_t seed = 1; seed <= 20; seed++){
		Params fp = dp;
		fp.seed = seed, fp.features = true;
		const Hill h(fp);
		for(const Hill::Feature &f : h.features){
			assert(h.in_lane(f) && h.on_track(f.x - 0.5f, f.z - 0.5f));
			in_lanes++;
		}
	}
	assert(in_lanes > 10);
	printf("hill.h: the default circuit %zu turns, %zu fences, %zu reliefs; 20 "
			"seeds, %d pits and rocks in its lanes\n", d.path.size() - 1,
			d.fences.size(), d.reliefs.size(), in_lanes);
	printf("hill.h: self test passed; %dx%dx%d voxels, rise %.1f m, "
			"%.1f%% stones in the shell; 50 hills, %d pits and %d rocks; the "
			"outside flush with the edge within %.2f voxels\n",
			a.size_x(), a.size_y(), a.size_z(), a.rise / U,
			100.0f * stone / (sand + stone), pits, rocks, worst);
	return 0;
}
#endif
